import { describe, expect, it } from 'vitest';
import type { SDKMessage } from '@anthropic-ai/claude-agent-sdk';
import { normalizeMessage, parseOutcome, summarizeToolInput } from './adapter.ts';

const ROOT = '/repo';

function message( data: Record<string, unknown> ): SDKMessage {
	return { uuid: 'u1', session_id: 's1', ...data } as unknown as SDKMessage;
}

describe( 'normalizeMessage', () => {
	it( 'reads the session id and model from the init message', () => {
		const result = normalizeMessage( message( { type: 'system', subtype: 'init', model: 'claude-x' } ), ROOT );

		expect( result.sessionId ).toBe( 's1' );
		expect( result.items ).toEqual( [ { kind: 'system', id: 'u1', text: 'Session started (claude-x).' } ] );
	} );

	it( 'turns assistant text and tool calls into items, and records written files', () => {
		const result = normalizeMessage(
			message( {
				type: 'assistant',
				parent_tool_use_id: null,
				message: {
					content: [
						{ type: 'thinking', thinking: 'hidden' },
						{ type: 'text', text: 'Bumping versions.' },
						{ type: 'text', text: '   ' },
						{ type: 'tool_use', id: 't1', name: 'Edit', input: { file_path: '/repo/readme.txt' } },
						{ type: 'tool_use', id: 't2', name: 'Bash', input: { command: 'git   status\n' } },
					],
				},
			} ),
			ROOT
		);

		expect( result.items ).toEqual( [
			{ kind: 'text', id: 'u1-1', text: 'Bumping versions.', subagent: false },
			{ kind: 'tool', id: 't1', name: 'Edit', summary: 'readme.txt', subagent: false },
			{ kind: 'tool', id: 't2', name: 'Bash', summary: 'git status', subagent: false },
		] );
		expect( result.filesWritten ).toEqual( [ '/repo/readme.txt' ] );
	} );

	it( 'marks subagent messages', () => {
		const result = normalizeMessage(
			message( { type: 'assistant', parent_tool_use_id: 'agent-1', message: { content: [ { type: 'text', text: 'Hi' } ] } } ),
			ROOT
		);

		expect( result.items[ 0 ] ).toMatchObject( { kind: 'text', subagent: true } );
	} );

	it( 'turns tool results into items, with string or block content and error state', () => {
		const result = normalizeMessage(
			message( {
				type: 'user',
				parent_tool_use_id: null,
				message: {
					content: [
						{ type: 'tool_result', tool_use_id: 't1', content: 'ok' },
						{ type: 'tool_result', tool_use_id: 't2', is_error: true, content: [ { type: 'text', text: 'boom' }, { type: 'image' } ] },
						{ type: 'text', text: 'not a tool result' },
					],
				},
			} ),
			ROOT
		);

		expect( result.items ).toEqual( [
			{ kind: 'tool_result', id: 'u1-0', toolUseId: 't1', ok: true, preview: 'ok', subagent: false },
			{ kind: 'tool_result', id: 'u1-1', toolUseId: 't2', ok: false, preview: 'boom\n[image]', subagent: false },
		] );
	} );

	it( 'truncates long tool output', () => {
		const result = normalizeMessage(
			message( { type: 'user', message: { content: [ { type: 'tool_result', tool_use_id: 't', content: 'x'.repeat( 5000 ) } ] } } ),
			ROOT
		);
		const item = result.items[ 0 ];

		expect( item.kind === 'tool_result' && item.preview.length ).toBe( 4001 );
	} );

	it( 'skips a user message whose content is a plain string (the command prompt echo)', () => {
		expect( normalizeMessage( message( { type: 'user', message: { content: '/wpsp-prep-release 4.17.5' } } ), ROOT ).items ).toEqual( [] );
	} );

	it( 'reads a successful result with cost and duration', () => {
		const result = normalizeMessage(
			message( { type: 'result', subtype: 'success', is_error: false, result: 'Done.', total_cost_usd: 0.42, duration_ms: 9000 } ),
			ROOT
		);

		expect( result.isResult ).toBe( true );
		expect( result.costUsd ).toBe( 0.42 );
		expect( result.items[ 0 ] ).toEqual( { kind: 'result', id: 'u1', ok: true, text: 'Done.', costUsd: 0.42, durationMs: 9000 } );
	} );

	it( 'reads an error result, falling back to its errors list', () => {
		const result = normalizeMessage(
			message( { type: 'result', subtype: 'error_max_turns', is_error: true, errors: [ 'Too many turns' ] } ),
			ROOT
		);

		expect( result.items[ 0 ] ).toMatchObject( { kind: 'result', ok: false, text: 'Too many turns', costUsd: null, durationMs: null } );
	} );

	it( 'treats a success result with is_error as a failure', () => {
		const result = normalizeMessage( message( { type: 'result', subtype: 'success', is_error: true, result: 'API error' } ), ROOT );

		expect( result.items[ 0 ] ).toMatchObject( { ok: false, text: 'API error' } );
	} );

	it( 'ignores message types it does not render, and malformed content', () => {
		expect( normalizeMessage( message( { type: 'stream_event' } ), ROOT ).items ).toEqual( [] );
		expect( normalizeMessage( message( { type: 'assistant', message: { content: 'oops' } } ), ROOT ).items ).toEqual( [] );
		expect( normalizeMessage( message( { type: 'assistant' } ), ROOT ).items ).toEqual( [] );
	} );
} );

describe( 'summarizeToolInput', () => {
	it( 'keeps paths outside the repo absolute', () => {
		expect( summarizeToolInput( 'Read', { file_path: '/elsewhere/a.md' }, ROOT ) ).toBe( '/elsewhere/a.md' );
	} );

	it( 'summarizes common tools', () => {
		expect( summarizeToolInput( 'Grep', { pattern: '{next}' }, ROOT ) ).toBe( '{next}' );
		expect( summarizeToolInput( 'Agent', { description: 'Write newsletter' }, ROOT ) ).toBe( 'Write newsletter' );
		expect( summarizeToolInput( 'Skill', { skill: 'gemini-image-generator', args: '--x' }, ROOT ) ).toBe( 'gemini-image-generator --x' );
		expect( summarizeToolInput( 'AskUserQuestion', { questions: [] }, ROOT ) ).toBe( 'Asked you a question' );
		expect( summarizeToolInput( 'mcp__x__y', { a: 1 }, ROOT ) ).toBe( '{"a":1}' );
	} );

	it( 'copes with missing or wrongly typed input', () => {
		expect( summarizeToolInput( 'Bash', null, ROOT ) ).toBe( '' );
		expect( summarizeToolInput( 'Read', { file_path: 42 }, ROOT ) ).toBe( '' );
		expect( summarizeToolInput( 'Unknown', {}, ROOT ) ).toBe( '' );
	} );

	it( 'truncates a long summary', () => {
		expect( summarizeToolInput( 'Bash', { command: 'a'.repeat( 500 ) }, ROOT ) ).toHaveLength( 241 );
	} );
} );

describe( 'parseOutcome', () => {
	const block = ( data: unknown ) => '```json\n' + JSON.stringify( data, null, 2 ) + '\n```';

	it( 'reads the release_console block at the end of a summary', () => {
		const text = `All done.\n\n${ block( {
			release_console: { status: 'ok', summary: 'Bumped 7 files.', files: [ 'readme.txt' ], followups: [ 'Review the changelog' ] },
		} ) }`;

		expect( parseOutcome( text ) ).toEqual( {
			status: 'ok',
			summary: 'Bumped 7 files.',
			files: [ 'readme.txt' ],
			followups: [ 'Review the changelog' ],
		} );
	} );

	it( 'uses the last report when there are several, and skips other json blocks', () => {
		const text = [
			block( { release_console: { status: 'blocked', summary: 'first' } } ),
			block( { release_console: { status: 'ok', summary: 'second' } } ),
			block( { unrelated: true } ),
		].join( '\n' );

		expect( parseOutcome( text )?.summary ).toBe( 'second' );
	} );

	it( 'fills in missing fields and drops non-string list items', () => {
		expect( parseOutcome( block( { release_console: { status: 'failed', files: [ 'a', 3, null ], followups: 'x' } } ) ) ).toEqual( {
			status: 'failed',
			summary: '',
			files: [ 'a' ],
			followups: [],
		} );
	} );

	it.each( [
		[ 'no block', 'Done.' ],
		[ 'an unknown status', '```json\n{"release_console":{"status":"great"}}\n```' ],
		[ 'broken json', '```json\n{"release_console":\n```' ],
		[ 'a block without the key', '```json\n{"status":"ok"}\n```' ],
		[ 'a different language', '```js\n{"release_console":{"status":"ok"}}\n```' ],
	] )( 'returns null for %s', ( _, text ) => {
		expect( parseOutcome( text ) ).toBeNull();
	} );

	it( 'is attached to result messages', () => {
		const result = normalizeMessage(
			message( { type: 'result', subtype: 'success', is_error: false, result: block( { release_console: { status: 'blocked', summary: 'PR not merged' } } ) } ),
			ROOT
		);

		expect( result.outcome ).toMatchObject( { status: 'blocked', summary: 'PR not merged' } );
	} );
} );
